// lib/sounds.ts
//
// Tiny sound-effects helper. Sounds are generated by the browser (Web Audio),
// so there are NO audio files to download, copy or host.
//
//   playSuccess()  - soft rising two-note chime
//   playWarning()  - single soft mid note
//   playError()    - gentle low descending two-note "uh-oh" (no buzzer)
//
// Staff can mute it from the browser console or a toggle with setSoundEnabled(false).

const STORAGE_KEY = 'ifix-sound'

let ctx: AudioContext | null = null
let primed = false

function createContext(): AudioContext | null {
  if (typeof window === 'undefined') return null
  try {
    const AC: typeof AudioContext | undefined =
      window.AudioContext || (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext
    if (!AC) return null
    if (!ctx) ctx = new AC()
    return ctx
  } catch {
    return null
  }
}

// Browsers only allow audio after the person has interacted with the page.
// Create/resume the audio context on the first click or key press, so sounds
// that fire later (e.g. after a database call finishes) are still allowed.
if (typeof window !== 'undefined' && !primed) {
  primed = true
  const prime = () => {
    const c = createContext()
    if (c && c.state === 'suspended') c.resume().catch(() => {})
  }
  window.addEventListener('pointerdown', prime, { once: false, passive: true })
  window.addEventListener('keydown', prime, { once: false, passive: true })
}

export function isSoundEnabled(): boolean {
  try {
    return window.localStorage.getItem(STORAGE_KEY) !== 'off'
  } catch {
    return true
  }
}

export function setSoundEnabled(enabled: boolean) {
  try {
    window.localStorage.setItem(STORAGE_KEY, enabled ? 'on' : 'off')
  } catch {
    /* storage unavailable - ignore */
  }
}

// One soft, bell-like note: sine wave + quiet octave overtone, slow fade-out.
function note(c: AudioContext, freq: number, startAt: number, duration: number, volume: number) {
  const out = c.createGain()
  out.gain.setValueAtTime(0.0001, startAt)
  out.gain.exponentialRampToValueAtTime(volume, startAt + 0.02)
  out.gain.exponentialRampToValueAtTime(0.0001, startAt + duration)
  out.connect(c.destination)

  const partials: Array<[number, number]> = [
    [1, 1],
    [2, 0.18],
  ]
  for (const [mult, level] of partials) {
    const osc = c.createOscillator()
    const g = c.createGain()
    osc.type = 'sine'
    osc.frequency.setValueAtTime(freq * mult, startAt)
    g.gain.setValueAtTime(level, startAt)
    osc.connect(g)
    g.connect(out)
    osc.start(startAt)
    osc.stop(startAt + duration + 0.02)
  }
}

function play(fn: (c: AudioContext, t: number) => void) {
  if (!isSoundEnabled()) return
  const c = createContext()
  if (!c) return
  try {
    if (c.state === 'suspended') c.resume().catch(() => {})
    fn(c, c.currentTime + 0.01)
  } catch {
    /* never let a sound problem break scanning */
  }
}

// Success: G5 -> C6, pleasant little chime
export function playSuccess() {
  play((c, t) => {
    note(c, 784, t, 0.28, 0.12)
    note(c, 1047, t + 0.1, 0.4, 0.12)
  })
}

// Warning / info: one soft D5 note
export function playWarning() {
  play((c, t) => {
    note(c, 587, t, 0.35, 0.12)
  })
}

// Error: soft low E4 -> C4, calm but clearly different from success
export function playError() {
  play((c, t) => {
    note(c, 330, t, 0.32, 0.16)
    note(c, 262, t + 0.16, 0.5, 0.16)
  })
}